// Generate local byte-preserving GLB script assets; originals are read-only.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const base=__dirname,lab=path.resolve(base,'../../..');
const intake=JSON.parse(fs.readFileSync(path.join(lab,'SCIENCE_LAB/CASE_STUDIES/NEXAH_TRANSITION_IDENTIFIABILITY_OBSERVATORY_V1_2026-10-07/GEOMETRIA_NOVA_RESONANCE_CATHEDRAL_INTAKE_2026-10-07.json'),'utf8'));
const labels={RC08:'Cathedral 0.8 · Originalanimationen',RC88:'Cathedral 8.8 · Fusion',PRIMEWEB:'Prime Web · Ulam 3D',QPLAY:'Quaternion Playground'};
// Same bundled renderer, classic-script wrapper for direct file:// reading.
const vendor=fs.readFileSync(path.join(base,'assets/vendor/model-viewer.min.js'),'utf8');
const end=/export\{[^}]+\};\s*\/\/# sourceMappingURL=model-viewer.min.js.map\s*$/;
if(!end.test(vendor))throw Error('Unexpected renderer export footer; do not transform blindly');
fs.writeFileSync(path.join(base,'assets/vendor/a0-model-viewer-classic.js'),'/* Generated classic wrapper of bundled model-viewer; license retained below. */\n(function(){\n'+vendor.replace(end,'')+'\n})();\n');
const records=[];
for(const id of Object.keys(labels)){
 const a=intake.model_assets.find(x=>x.id===id),b=fs.readFileSync(a.path);
 const hash=crypto.createHash('sha256').update(b).digest('hex');if(hash!==a.sha256)throw Error('source hash drift '+id);
 const count=b.readUInt32LE(12),doc=JSON.parse(b.subarray(20,20+count).toString());
 const file='assets/a0-cathedral-'+id.toLowerCase()+'.packed.js';
 const data={id,base64:b.toString('base64')};
 fs.writeFileSync(path.join(base,file),'/* Generated byte-preserving local GLB snapshot. Original source hash in manifest. */\nwindow.A0CathedralPacked=window.A0CathedralPacked||{};window.A0CathedralPacked['+JSON.stringify(id)+']='+JSON.stringify(data.base64)+';\n');
 records.push({id,label:labels[id],file,source:a.path,filename:a.file,sha256:hash,bytes:b.length,nodes:doc.nodes.length,animations:(doc.animations||[]).map(a=>a.name)});
}
fs.writeFileSync(path.join(base,'assets/a0-cathedral-viewer-manifest.json'),JSON.stringify({status:'INTERNAL_SOURCE_SNAPSHOTS_NOT_RETARGETED',models:records},null,2)+'\n');
fs.writeFileSync(path.join(base,'assets/a0-cathedral-viewer-manifest.js'),'window.A0CathedralModels='+JSON.stringify(records)+';\n');
console.log(JSON.stringify({status:'PASS',models:records.map(r=>({id:r.id,bytes:r.bytes,animations:r.animations.length})),source_files_modified:0}));

